import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Short effects in `assets/sounds/` (generated by `tool/sound_gen.py`).
enum Sfx { move, star, wrong, lava, promote, taskWon, lessonDone, whoosh, hitSparkle, poof }

/// Background loops in `assets/sounds/`.
enum Music { map, lesson }

/// Effects + one music loop. Like the narrator, a missing plugin (widget
/// tests) or a busy audio session never breaks the game.
class Sounds {
  /// Kept low so the narrator stays on top.
  static const musicVolume = .18;

  bool sfxOn = true;
  bool musicOn = true;

  AudioPlayer? _music;
  Music? _track;

  static String _file(Sfx s) => switch (s) {
    Sfx.taskWon => 'task_won',
    Sfx.lessonDone => 'lesson_done',
    Sfx.hitSparkle => 'hit_sparkle',
    _ => s.name,
  };

  Future<void> play(Sfx s, {double volume = .8}) async {
    if (!sfxOn) return;
    try {
      final p = AudioPlayer();
      await p.setPlayerMode(PlayerMode.lowLatency);
      p.onPlayerComplete.first.then((_) => p.dispose());
      await p.play(AssetSource('sounds/${_file(s)}.mp3'), volume: volume);
    } on Object catch (e) {
      debugPrint('sfx: $e');
    }
  }

  /// Switches the loop; the same track keeps playing, null stops it.
  Future<void> music(Music? track) async {
    if (track == _track) return;
    _track = track;
    try {
      final p = _music ??= AudioPlayer(playerId: 'music')..setReleaseMode(ReleaseMode.loop);
      await p.stop();
      if (track == null || !musicOn) return;
      await p.play(AssetSource('sounds/${track.name}.mp3'), volume: musicVolume);
    } on Object catch (e) {
      debugPrint('music: $e');
    }
  }

  Future<void> dispose() async => _music?.dispose();
}
